import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Chart as ChartJS, ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement } from 'chart.js';
import { Pie, Bar } from 'react-chartjs-2';
import { FaChartPie, FaChartBar, FaRocket, FaCheckCircle, FaCircle, FaFire, FaTarget } from 'react-icons/fa';
import { motion } from 'framer-motion';
import axios from 'axios';

ChartJS.register(ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement);

const ProgressStats = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) fetchData();
    }, [user]);

    const fetchData = async () => {
        try {
            const res = await axios.get(`http://localhost:8081/api/tasks/user/${user.id}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            console.log('📊 Tasks data:', res.data);
            setTasks(res.data);
            setLoading(false);
        } catch (error) {
            console.error('❌ Failed to fetch:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="d-flex justify-content-center align-items-center" style={{ height: '60vh' }}>
                <div className="spinner-border text-primary" role="status">
                    <span className="visually-hidden">Loading...</span>
                </div>
            </div>
        );
    }

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted === true).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    const javaCompleted = tasks.filter(t => t.javaCompleted === true).length;
    const leetcodeCompleted = tasks.filter(t => t.leetcodeCompleted === true).length;
    const dsaCompleted = tasks.filter(t => t.dsaCompleted === true).length;
    const sqlCompleted = tasks.filter(t => t.sqlCompleted === true).length;
    const projectCompleted = tasks.filter(t => t.projectCompleted === true).length;
    const githubCompleted = tasks.filter(t => t.githubCompleted === true).length;

    const calculateStreak = () => {
        let streak = 0;
        const sorted = [...tasks].sort((a, b) => a.day - b.day);
        for (const task of sorted) {
            if (task.overallCompleted === true) streak++;
            else break;
        }
        return streak;
    };

    const streak = calculateStreak();

    const pieData = {
        labels: ['Completed ✅', 'Remaining ⏳'],
        datasets: [{
            data: [completedTasks, Math.max(0, totalTasks - completedTasks)],
            backgroundColor: ['#34d399', '#e5e7eb'],
            borderWidth: 0,
        }],
    };

    const barData = {
        labels: ['Java', 'LeetCode', 'DSA', 'SQL/API', 'Project', 'GitHub'],
        datasets: [{
            label: 'Tasks Completed',
            data: [javaCompleted, leetcodeCompleted, dsaCompleted, sqlCompleted, projectCompleted, githubCompleted],
            backgroundColor: ['#4f8cf7', '#7c5cfc', '#34d399', '#fb923c', '#f472b6', '#06b6d4'],
            borderRadius: 6,
        }],
    };

    const chartOptions = {
        responsive: true,
        plugins: {
            legend: {
                labels: { color: '#6a6a82', font: { family: 'Inter', size: 12 } },
            },
        },
        scales: {
            y: {
                beginAtZero: true,
                grid: { color: '#f0f0f0' },
                ticks: { color: '#6a6a82' },
            },
            x: {
                grid: { display: false },
                ticks: { color: '#6a6a82' },
            },
        },
    };

    const statsCards = [
        { label: 'Completion Rate', value: `${completionRate}%`, icon: FaChartPie, color: 'text-green-500', bg: 'bg-green-50' },
        { label: 'Tasks Done', value: `${completedTasks}/${totalTasks}`, icon: FaCheckCircle, color: 'text-indigo-500', bg: 'bg-indigo-50' },
        { label: 'Streak', value: `${streak} days`, icon: FaFire, color: 'text-orange-500', bg: 'bg-orange-50' },
        { label: 'Target', value: '30 days', icon: FaTarget, color: 'text-purple-500', bg: 'bg-purple-50' },
    ];

    return (
        <div className="container-fluid p-0">
            {/* Header */}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="hero-gradient mb-4">
                <div className="d-flex align-items-center gap-3">
                    <FaChartBar size={28} className="text-white" />
                    <div>
                        <h1 className="text-white fw-bold fs-2 mb-0">📊 Progress Analytics</h1>
                        <p className="text-white/70 mb-0">Track your learning journey</p>
                    </div>
                </div>
            </motion.div>

            {/* Stats Cards */}
            <div className="row g-4 mb-4">
                {statsCards.map((stat, index) => {
                    const Icon = stat.icon;
                    return (
                        <motion.div key={index} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * 0.1 }} className="col-6 col-lg-3">
                            <div className="premium-card glass-card">
                                <div className="d-flex justify-content-between align-items-center">
                                    <div>
                                        <p className="text-muted small fw-medium mb-1">{stat.label}</p>
                                        <h2 className="fw-bold mb-0">{stat.value}</h2>
                                    </div>
                                    <div className={`icon-wrapper ${stat.bg}`}><Icon className={stat.color} size={24} /></div>
                                </div>
                            </div>
                        </motion.div>
                    );
                })}
            </div>

            {/* Charts */}
            <div className="row g-4">
                <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="col-lg-6">
                    <div className="premium-card glass-card">
                        <h5 className="fw-semibold mb-4">📊 Overall Completion</h5>
                        <div className="mx-auto" style={{ maxWidth: '300px' }}>
                            <Pie data={pieData} options={chartOptions} />
                        </div>
                        <div className="text-center mt-4">
                            <p className="text-muted small">{completedTasks} of {totalTasks} tasks completed</p>
                            {totalTasks === 0 && <p className="text-warning small mt-2">⚠️ No tasks found! Go to Daily Tracker and create tasks.</p>}
                        </div>
                    </div>
                </motion.div>

                <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="col-lg-6">
                    <div className="premium-card glass-card">
                        <h5 className="fw-semibold mb-4">📊 Task-wise Completion</h5>
                        <Bar data={barData} options={chartOptions} />
                        {totalTasks === 0 && <p className="text-warning small text-center mt-4">⚠️ No data to display. Create tasks in Daily Tracker!</p>}
                    </div>
                </motion.div>
            </div>

            {/* Motivation */}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="mt-4 hero-gradient">
                <div className="row align-items-center">
                    <div className="col-md-8">
                        <h2 className="text-white fw-bold fs-3">🚀 Keep Going!</h2>
                        <p className="text-white/80">You're making great progress! Consistency is key to mastering development skills.</p>
                        <div className="d-flex flex-wrap gap-2 mt-2">
                            <span className="badge bg-white/20 text-white px-3 py-2 rounded-pill">#CodeEveryday</span>
                            <span className="badge bg-white/20 text-white px-3 py-2 rounded-pill">#NeverGiveUp</span>
                            <span className="badge bg-white/20 text-white px-3 py-2 rounded-pill">#YouCanDoIt</span>
                            <span className="badge bg-white/20 text-white px-3 py-2 rounded-pill">#StayConsistent</span>
                        </div>
                    </div>
